begin;
create table if not exists public.lingxifield_provider_connections(connection_id uuid primary key default gen_random_uuid(),owner_id uuid not null,name text not null,adapter text not null check(adapter in ('openai-compatible','native','local')),base_url text,model text,capabilities jsonb not null default '[]'::jsonb,secret_ref text,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.lingxifield_provider_capability_health(connection_id uuid not null references public.lingxifield_provider_connections(connection_id) on delete cascade,owner_id uuid not null,capability text not null,health numeric not null default 1 check(health>=0 and health<=1),latency_ms numeric not null default 0,cost numeric not null default 0,privacy numeric not null default 1 check(privacy>=0 and privacy<=1),updated_at timestamptz not null default now(),primary key(connection_id,capability));
alter table public.lingxifield_provider_connections enable row level security;alter table public.lingxifield_provider_capability_health enable row level security;
drop policy if exists lingxifield_provider_connections_owner on public.lingxifield_provider_connections;create policy lingxifield_provider_connections_owner on public.lingxifield_provider_connections for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
drop policy if exists lingxifield_provider_capability_health_owner on public.lingxifield_provider_capability_health;create policy lingxifield_provider_capability_health_owner on public.lingxifield_provider_capability_health for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
commit;
